CREATE TABLE IF NOT EXISTS employee_onboarding_tasks (id UUID PRIMARY KEY,employer_id UUID NOT NULL REFERENCES employer_accounts(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')),due_date DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS employee_training_records (id UUID PRIMARY KEY,employer_id UUID NOT NULL REFERENCES employer_accounts(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','in_progress','completed')),completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS employee_performance_reviews (id UUID PRIMARY KEY,employer_id UUID NOT NULL REFERENCES employer_accounts(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE,reviewer_employee_id UUID REFERENCES workforce_employees(id),rating INTEGER CHECK(rating BETWEEN 1 AND 5),summary TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS employee_document_records (id UUID PRIMARY KEY,employer_id UUID NOT NULL REFERENCES employer_accounts(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE,title TEXT NOT NULL,external_url TEXT,acknowledged_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS employee_notifications (id UUID PRIMARY KEY,employer_id UUID NOT NULL REFERENCES employer_accounts(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE,title TEXT NOT NULL,body TEXT NOT NULL,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS employee_leave_balances (employer_id UUID NOT NULL REFERENCES employer_accounts(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE,leave_year INTEGER NOT NULL,annual_allowance_days INTEGER NOT NULL DEFAULT 0 CHECK(annual_allowance_days >= 0),PRIMARY KEY(employer_id,employee_id,leave_year));
CREATE INDEX IF NOT EXISTS idx_onboarding_tenant ON employee_onboarding_tasks(employer_id,employee_id);
CREATE INDEX IF NOT EXISTS idx_training_tenant ON employee_training_records(employer_id,employee_id);
CREATE INDEX IF NOT EXISTS idx_review_tenant ON employee_performance_reviews(employer_id,employee_id);
CREATE INDEX IF NOT EXISTS idx_notifications_tenant ON employee_notifications(employer_id,employee_id,created_at);
